import base64,json,subprocess,uuid,time
from pathlib import Path
r=Path('/dataset/shaoshitong/search-r1-rl/bapo-aligned-cohost-node11-v11-20261009');old=r/'runs/formal-aligned-em200-16c570e111f947e2b0026983df2f7938-3359'
assert (old/'cleanup-exit-code.txt').read_text().strip()=='0'
assert not Path('/proc/1598631').exists()
d=r/'tools/eval150';d.mkdir(exist_ok=True)
files={'eval150.sbatch': '', 'worker.sh': '', 'inner.sh': '', 'evaluate.py': ''}
for n,b in files.items():
 p=d/n;raw=base64.b64decode(b)
 if p.exists():assert p.read_bytes()==raw
 else:p.write_bytes(raw)
subprocess.run([str(r/'env/bin/python'),'-m','py_compile',str(d/'evaluate.py')],check=True)
i=r/'scheduler-head/eval150-submit-intent.json';receipt=r/'scheduler-head/eval150-submit-receipt.json'
assert not i.exists() and not receipt.exists(),'existing intent: inspect; never repeat'
token=uuid.uuid4().hex;i.write_text(json.dumps(dict(token=token,time=time.time(),human='stop200;eval1508gpuBS512',source='4c2a409')))
p=subprocess.run(['sbatch','--parsable','--comment=BAPO_EVAL150:'+token,str(d/'eval150.sbatch'),token],capture_output=True,text=True,timeout=45)
(r/'scheduler-head/eval150-sbatch-response.json').write_text(json.dumps(dict(exit=p.returncode,stdout=p.stdout,stderr=p.stderr)))
assert p.returncode==0,p.stderr
job=p.stdout.strip().split(';')[0];assert job.isdigit()
x=dict(job=job,run=str(r/'runs'/('eval150-final51713-'+token+'-'+job)),token=token,source='4c2a409',batch_size=512,gpus=8);receipt.write_text(json.dumps(x));print(json.dumps(x))
